def vstack(a, b):
    """The grid with b placed below a."""
    return [list(r) for r in a] + [list(r) for r in b]

def hstack(a, b):
    """The grid with b placed to the right of a."""
    return [list(ra) + list(rb) for ra, rb in zip(a, b)]

